select DISTINCT a.id, a.username, a.realname, a.work_no, a.avatar, a.birthday, a.sex, a.email, a.phone, a.telephone, a.depart_ids, a.user_identity, a.status, a.activiti_sync, a.del_flag, a.create_by, a.create_time, a.update_by, a.update_time, a.home_path, a.customer_type, a.user_type, a.kyc_status, a.inviter_id, a.biz_owner_user_id, a.tenant_id, a.nation, a.country from sys_user a left join sys_user_role sur on sur.user_id = a.id where a.del_flag = 0 and a.status = 1 and a.username!='_reserve_user_external' and sur.role_id=#{roleId}
and (a.username like #{bindKeyword} or a.realname like #{bindKeyword})
and a.id in ( select user_id from sys_user_tenant where tenant_id = #{tenantId} and status = '1' )
and a.id not in
#{userId}

